import * as cms from './cms.js';
import * as careSite from './care-site.js';
import * as careAdmin from './care-admin.js';
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
const brand='<a class="brand" href="/" aria-label="Stillwell home"><span class="brand-mark" aria-hidden="true">s</span>stillwell</a>';
let posts=globalThis.__POSTS__||JSON.parse(document.querySelector('#initial-posts')?.textContent||'[]');
let providers=globalThis.__PROVIDERS__||JSON.parse(document.querySelector('#initial-providers')?.textContent||'[]');
let requests=[];
let activeCare=0,blogCategory='All articles',blogSearch='',adminFilter='All posts',adminSearch='';
let editorDirty=false,uploadPending=false,savePending=false,loadError='';let theme;
try{theme=localStorage.getItem('stillwell-theme')}catch{}
document.documentElement.dataset.theme=theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
const care=[
{name:'Individual therapy',heading:'A space that’s just yours.',text:'Explore what’s on your mind in a one-to-one conversation. Find room for the everyday, the unexpected, and everything in between.',image:'/assets/talk.jpg',alt:'A quiet, light-filled room with comfortable seating',details:['One-to-one support','At your own pace']},
{name:'Couples therapy',heading:'Make room for each other.',text:'A shared space to understand each other, explore the conversations that matter, and think about what comes next together.',image:'/assets/walk.jpg',alt:'A family spending time together outdoors',details:['Shared conversations','Thoughtful support']},
{name:'Young adult support',heading:'Find your own footing.',text:'Changing routines, new relationships, and big decisions. Explore support for the transitions that come with early adulthood.',image:'/assets/slow.jpg',alt:'A peaceful landscape in natural light',details:['For adults 18+','Life transitions']}
];
const legacyFaqs=[['How do I get started?','Explore the care options and choose what feels closest to your needs. In a live service, the next step would be a short introductory enquiry. This preview lets you explore that experience without booking an appointment.'],['Can I choose how we meet?','The proposed experience supports online and in-person preferences. Available formats, locations, and appointment times will be confirmed by the care team before launch.'],['What if I’m not sure what I need?','You can begin with a general enquiry. You do not need to choose a service or share personal details to ask how the process works.'],['How much does it cost?','Fees and any payment or insurance arrangements will be added once they are confirmed by the client. This preview does not take payments.'],['How is my information handled?','This design preview does not send enquiry form entries to a care team. The journal uses a secure administrator account and shared online storage. Final privacy terms and contact delivery will be confirmed before the care service launches.']];
function nav(){return `<header class="header"><div class="wrap nav">${brand}<nav class="nav-links" aria-label="Main navigation">${careSite.navigation()}</nav><div class="nav-end"><a class="text-link" href="/therapists">Find a therapist</a><a class="btn" href="/get-started">Get started ${arrow}</a><button class="menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">☰</button></div></div></header>`;}
function footer(){return `<footer class="wrap footer"><div class="footer-top"><div class="footer-brand">${brand}<p>A little space for your mind.<br>Care, with India in mind.</p><a href="/about">About us</a> · <a href="/contact">Contact</a></div>${careSite.footerLinks()}</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Stillwell.</span><p>Enquiries are in testing mode. No appointment is booked through this website.</p><a href="/privacy">Privacy & terms</a><a href="/admin">Administrator</a><button class="icon-button" data-action="theme" aria-label="Switch color theme">◐</button></div></footer>`;}
function layout(content){return `${nav()}<main id="main">${content}</main>${footer()}`;}
function carePanel(){const c=care[activeCare];return `<div class="care-copy reveal"><h3>${c.heading}</h3><p>${c.text}</p><ul class="care-list">${c.details.map(d=>`<li>${d}</li>`).join('')}</ul><button class="text-link" data-action="care" data-choice="${activeCare}">Explore ${c.name.toLowerCase()} ${arrow}</button></div><img src="${c.image}" alt="${c.alt}" loading="lazy" width="650" height="420">`;}
function careSection(){return `<section class="wrap section" id="care"><div class="section-head"><h2 class="intro-title">Care that meets you<br>where you are.</h2><p>There’s no one way to feel. There’s no one way to begin.</p></div><div class="care-tabs" role="tablist" aria-label="Care options">${care.map((c,i)=>`<button class="tab" role="tab" id="care-tab-${i}" aria-controls="care-panel" aria-selected="${activeCare===i}" tabindex="${activeCare===i?0:-1}" data-action="care-tab" data-index="${i}">${c.name}</button>`).join('')}</div><div class="care-panel" id="care-panel" role="tabpanel" aria-labelledby="care-tab-${activeCare}">${carePanel()}</div></section>`;}
function howSection(){return `<section class="wrap" id="how-it-works"><div class="how-section"><div class="how-intro"><div><h2>A first step.<br>At your pace.</h2><p>Starting something new can feel big. We make space for the small steps.</p></div><a href="/contact" class="text-link">Let’s talk about it ${arrow}</a></div><div class="how-steps">${[['↗','Tell us a little about you','Start with what you’re looking for. Share only what you’re comfortable sharing.'],['↔','Find a connection','Explore the kind of support and conversation that feels right for you.'],['✓','Make space for yourself','Choose a time and a format that work with your everyday life.']].map(([icon,title,text])=>`<div class="step"><span class="step-icon" aria-hidden="true">${icon}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}</div></div></section>`;}
function safeImage(src){if(typeof src==='string'&&/^https:\/\/ldwpuzcvjpuclcukboyq\.supabase\.co\/storage\/v1\/object\/public\/blog-images\/[a-zA-Z0-9._-]+$/.test(src))return src;return typeof src==='string'&&(/^\/assets\/[a-zA-Z0-9._-]+$/.test(src)||/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src))?src:'/assets/slow.jpg';}
function dateLabel(date){return new Date(date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}
function articleCard(p){return `<article class="article-card"><a href="/blog/${esc(p.slug)}" tabindex="-1" aria-hidden="true"><img src="${safeImage(p.image)}" alt="${esc(p.imageAlt||p.title)}" loading="lazy" width="600" height="460"></a><div><div class="article-meta"><span>${esc(p.category)}</span><span>${Math.max(2,Math.ceil(p.body.split(/\s+/).length/180))} min read</span></div><h3><a href="/blog/${esc(p.slug)}">${esc(p.title)}</a></h3><a class="text-link" href="/blog/${esc(p.slug)}">Read the story ${arrow}</a></div></article>`;}
function journalSection(){return `<section class="wrap section"><div class="section-head journal-heading"><div><h2>A little perspective.</h2><p>Thoughtful reads for being a little more human.</p></div><a href="/blog" class="text-link">Explore the journal ${arrow}</a></div><div class="article-grid">${posts.filter(p=>p.status==='published').slice(0,3).map(articleCard).join('')}</div></section>`;}
const faqs=careSite.helpTopics.slice(0,5);
function faqSection(){return `<section class="wrap section" style="padding-top:20px"><div class="faq-grid"><div><h2>A few things<br>you might wonder.</h2><p>It’s okay to have questions.<br>We’re here to make things clearer.</p><a href="/contact" class="text-link">Ask us something ${arrow}</a></div><div class="faq-list">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function cta(){return `<section class="wrap"><div class="cta"><div><h2>A little support.<br>A place to begin.</h2><p>Start wherever you are. We’ll meet you there.</p></div><button class="btn" data-action="care">Find your starting point ${arrow}</button></div></section>`;}
function home(){return layout(`<section class="wrap hero"><div class="hero-copy"><h1>A little space.<br>A lighter you.</h1><p>Therapy and psychiatric care in India, built around you and the life you’re living.</p><div class="hero-actions"><button class="btn" data-action="care">Find your care ${arrow}</button><a href="#how-it-works" class="text-link">How it works <span class="arrow" aria-hidden="true">↓</span></a></div></div><img class="hero-image" src="/assets/hero.webp" alt="A woman enjoying a quiet moment in the afternoon sunlight" fetchpriority="high" width="800" height="850"></section><div class="wrap"><div class="benefits"><span><i aria-hidden="true">✓</i> Your space, without judgment</span><span><i aria-hidden="true">↔</i> Support that fits your life</span><span><i aria-hidden="true">♡</i> A more human kind of care</span></div></div>${careSite.homeCare()}${careSite.careComparison()}${howSection()}${journalSection()}${faqSection()}${cta()}`);}
function blog(){return layout(`<div class="wrap page-top"><a class="crumb" href="/">Home / The journal</a><h1>A little perspective.</h1><p>Stories, questions, and everyday moments. A space to pause and find something that speaks to you.</p></div><section class="wrap" style="padding-bottom:80px" aria-label="Journal articles"><div class="filter-bar"><div class="care-tabs">${['All articles','Everyday wellbeing','Starting therapy','Relationships'].map(c=>`<button class="tab ${blogCategory===c?'active':''}" aria-pressed="${blogCategory===c}" data-action="blog-filter" data-category="${c}">${c}</button>`).join('')}</div><input class="search" id="blog-search" type="search" value="${esc(blogSearch)}" placeholder="Search the journal" aria-label="Search articles"></div><div class="article-grid blog-grid" id="blog-results">${blogResults()}</div></section>${careSite.journalExtra()}${cta()}`);}
function blogResults(){const found=posts.filter(p=>p.status==='published'&&(blogCategory==='All articles'||p.category===blogCategory)&&(p.title+' '+p.excerpt+' '+p.body).toLowerCase().includes(blogSearch.toLowerCase()));return found.length?found.map(articleCard).join(''):'<div class="empty"><h3>No stories found.</h3><p>Try a different word or explore all articles.</p><button class="btn light" data-action="reset-blog">Show all articles</button></div>';}
function markdown(body){const inline=t=>esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');const output=[];let paragraph=[];const flush=()=>{if(paragraph.length){output.push(`<p>${paragraph.map(inline).join('<br>')}</p>`);paragraph=[];}};for(const line of body.split(/\r?\n/)){if(/^##?\s/.test(line)){flush();output.push(`<h2>${inline(line.replace(/^##?\s+/,''))}</h2>`);}else if(!line.trim())flush();else paragraph.push(line);}flush();return output.join('');}
function article(slug){const p=posts.find(p=>p.slug===slug&&p.status==='published');if(!p)return notFound();return layout(`<article class="wrap"><div class="article-hero"><a href="/blog" class="text-link">← Back to the journal</a><h1>${esc(p.title)}</h1><p>${esc(p.excerpt)}</p><div class="article-meta"><span>${esc(p.category)}</span><span>${dateLabel(p.date)}</span></div><img src="${safeImage(p.image)}" alt="${esc(p.imageAlt||p.title)}" width="900" height="500"></div><div class="article-body">${markdown(p.body)}<p class="note">From the Stillwell concept journal. Sample editorial content for this website preview, not personal clinical guidance.</p><a href="/blog" class="text-link">More from the journal ${arrow}</a></div></article><div style="height:70px"></div>${cta()}`);}
function about(){return layout(`<section class="wrap page-top"><a class="crumb" href="/">Home / About us</a><h1>More room to be human.</h1><p>Stillwell begins with a simple idea: support should make room for the whole person, not just the problem.</p></section><div class="wrap"><img class="about-image" src="/assets/hero.webp" alt="A quiet moment at home, surrounded by natural light" width="1300" height="600"></div><section class="wrap section"><h2>Care starts with listening.</h2><div class="values">${[['You set the pace','The first conversation is a starting point. You should have space to ask questions, think about your options, and decide what feels right.'],['A person, not a checklist','Your experiences, preferences, and everyday life belong in the conversation. There is no single story you need to fit.'],['Clarity from the beginning','Good information makes decisions easier. Our proposed care experience puts practical details and clear next steps where you can find them.'],['Room for everyday life','Support should fit into a real life. We are designing an experience that makes exploring options feel straightforward and human.']].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section>${careSite.aboutExtra()}${cta()}`);}
function contact(){return layout(`<div class="wrap page-top"><a class="crumb" href="/">Home / Get in touch</a><h1>Let’s talk.</h1><p>Have a question about care or how it works? You can start here.</p></div><section class="wrap contact-grid" style="padding-bottom:80px"><form class="form" id="contact-form"><div class="pair"><label>First name<input name="firstName" autocomplete="given-name" required maxlength="80"></label><label>Last name<input name="lastName" autocomplete="family-name" required maxlength="80"></label></div><label>Email address<input type="email" name="email" autocomplete="email" required maxlength="160"></label><label>What would you like to know?<select name="interest"><option>General enquiry</option><option>Individual therapy</option><option>Couples therapy</option><option>Young adult support</option></select></label><label>Your message<textarea name="message" maxlength="2000" required placeholder="Please keep your question general. No personal health details are needed."></textarea></label><label class="check-label"><input type="checkbox" required> I understand this is a website preview and my message will not be sent.</label><button class="btn" type="submit">Preview enquiry ${arrow}</button><p class="notice">Demo form. No email is sent and your enquiry is not stored.</p></form><aside class="contact-info"><h3>A little clarity first.</h3><p>You don’t need the perfect words. Ask about session formats, the process, or where to begin.</p><p>Service availability, fees, and contact details will be confirmed when the website launches.</p><p class="small">This preview is not a care service and cannot receive urgent requests.</p><a href="/services" class="text-link">Explore the care options ${arrow}</a></aside></section>${careSite.contactExtra()}`);}
function privacy(){return layout(`<section class="wrap section legal"><h1>Privacy & preview terms</h1><h2>About this website</h2><p>Stillwell is an illustrative website concept. The brand, services, and articles are sample content. No appointments, payments, or clinical services are offered through this preview.</p><h2>What is stored</h2><p>Journal posts and images are stored in Supabase. Only authorized administrators can edit them. Draft text is restricted to administrators; published articles and featured images are public. The administrator session and theme preference use browser storage.</p><h2>Contact forms</h2><p>The contact preview is not stored. Care, professional application, partnership, and referral test enquiries are saved in Supabase for authorized administrators. These include the contact details and preferences you enter and your consent. No automated email is sent or appointment booked. Please use test details and do not enter patient records or personal health information. Provider profiles marked verified and published by the administrator are public.</p><h2>Before launch</h2><p>The client must supply final privacy terms, business details, approved service content, and editorial review. The contact delivery service and final business policies must be configured before this becomes a live care service.</p></section>${careSite.privacyExtra()}`);}
function notFound(){return layout('<section class="wrap section"><h1>Let’s find your way back.</h1><p style="margin:25px 0">That page isn’t available. It may have moved or be unpublished.</p><a class="btn" href="/">Back to Stillwell</a></section>');}
function authenticated(){return !!cms.administrator;}
function adminShell(content){const links=[['/admin','All posts'],['/admin/new','Create a post'],['/admin/providers','Providers'],['/admin/enquiries','Enquiries'],['/blog','View journal ↗']];return `<div class="admin-shell"><aside class="sidebar"><div>${brand}<p class="small">Care & publishing workspace</p></div><nav aria-label="Portal navigation">${links.map(([href,label])=>`<a href="${href}" ${location.pathname===href||(href==='/admin/providers'&&location.pathname.startsWith(href+'/'))?'class="selected" aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="bottom"><button class="text-link" style="border:0;background:none" data-action="logout">Exit workspace ↗</button></div></aside><main class="admin-main" id="main">${content}</main></div>`;}
function login(){return layout(`<div class="wrap"><section class="login"><p class="small">Stillwell publishing</p><h1>A home for your words.</h1><p>Sign in to manage your journal, providers, and test enquiries.</p><form id="login-form" class="form"><label>Email address<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required minlength="8"></label><p id="login-error" role="alert" class="form-error"></p><button class="btn" type="submit">Sign in ${arrow}</button></form><p class="small">Administrator access only.</p><a class="text-link" href="/">← Back to the website</a></section></div>`);}
function admin(){return adminShell(`<div class="admin-header"><div><h1>Your journal</h1><p>A thoughtful space for every story.</p></div><a class="btn" href="/admin/new">+ Create a post</a></div><div class="notice">Signed in as ${esc(cms.administrator?.email)} · Changes are saved online.</div><div class="stats"><div class="stat"><span>Total stories</span><strong>${posts.length}</strong></div><div class="stat"><span>Published</span><strong>${posts.filter(p=>p.status==='published').length}</strong></div><div class="stat"><span>Drafts</span><strong>${posts.filter(p=>p.status==='draft').length}</strong></div></div><div class="filter-bar"><div class="care-tabs">${['All posts','Published','Drafts'].map(f=>`<button class="tab ${adminFilter===f?'active':''}" aria-pressed="${adminFilter===f}" data-action="admin-filter" data-filter="${f}">${f}</button>`).join('')}</div><input class="search" id="admin-search" type="search" aria-label="Search posts" placeholder="Search posts" value="${esc(adminSearch)}"></div><div id="admin-results">${adminResults()}</div>`);}
function adminResults(){const found=posts.filter(p=>(adminFilter==='All posts'||p.status===(adminFilter==='Published'?'published':'draft'))&&p.title.toLowerCase().includes(adminSearch.toLowerCase()));return found.length?`<div class="table-wrap"><table class="post-table"><thead><tr><th>Story</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody>${found.map(p=>`<tr><td><div class="post-cell"><img src="${safeImage(p.image)}" alt="" width="65" height="50"><div><strong><a href="/admin/edit/${esc(p.id)}">${esc(p.title)}</a></strong><small>${esc(p.category)}</small></div></div></td><td><span class="status ${p.status==='draft'?'draft':''}">${p.status==='published'?'Published':'Draft'}</span></td><td>${dateLabel(p.date)}</td><td><div class="row-actions"><a class="text-link" href="/admin/edit/${esc(p.id)}">Edit</a><button data-action="toggle-post" data-id="${esc(p.id)}">${p.status==='published'?'Unpublish':'Publish'}</button><button data-action="delete-post" data-id="${esc(p.id)}" aria-label="Delete ${esc(p.title)}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No posts here yet.</h3><p>Create a story or try another search.</p><a href="/admin/new" class="btn">Create a post</a></div>';}
function editor(id){if(id&&!posts.some(p=>p.id===id))return adminShell('<h1>Story not found</h1><p>It may have been deleted in another session.</p><a href="/admin">All posts</a>');const p=posts.find(p=>p.id===id)||{id:crypto.randomUUID(),slug:'',title:'',body:'',excerpt:'',image:'/assets/slow.jpg',imageAlt:'',category:'Everyday wellbeing',status:'draft',date:new Date().toISOString().slice(0,10)};return adminShell(`<div class="admin-header"><div><a class="text-link" href="/admin">← All posts</a><h1>${id?'Edit your story':'A new story starts here.'}</h1></div><button class="btn light" data-action="preview-post">Preview ${arrow}</button></div><form class="form" id="editor-form" data-id="${p.id}" data-version="${p.version||''}"><div class="editor-layout"><div class="editor-fields form"><label>Story title<input name="title" value="${esc(p.title)}" required maxlength="110" placeholder="Give your story a title"></label><label>Short introduction<textarea name="excerpt" style="min-height:85px" maxlength="260" placeholder="A sentence that invites the reader in">${esc(p.excerpt)}</textarea></label><div class="editor-toolbar" role="toolbar" aria-label="Text formatting"><button type="button" data-action="format" data-format="bold"><strong>B</strong></button><button type="button" data-action="format" data-format="italic"><em>I</em></button><button type="button" data-action="format" data-format="heading">Heading</button></div><label>Your story<textarea name="body" id="post-body" required maxlength="100000" placeholder="Start writing. Use the toolbar to add headings or emphasis.">${esc(p.body)}</textarea></label><p class="small">Use blank lines for paragraphs. Formatting is shown in Preview.</p></div><aside class="editor-settings form"><h3>Story details</h3><label>Featured image<img class="upload-preview" id="upload-preview" src="${safeImage(p.image)}" alt="Featured image preview"><input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="image" value="${safeImage(p.image)}"></label><p class="small">JPG, PNG, or WebP. Up to 2 MB.</p><label>Image description<input name="imageAlt" value="${esc(p.imageAlt||'')}" placeholder="Describe the image" maxlength="200"></label><label>Category<select name="category">${['Everyday wellbeing','Starting therapy','Relationships'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Article URL<input name="slug" maxlength="150" value="${esc(p.slug)}" placeholder="your-story-title" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" title="Use lowercase letters, numbers, and single hyphens"></label><label>Tags<input name="tags" value="${esc((p.tags||[]).join(', '))}" maxlength="600" placeholder="Separate with commas"></label><label>Search title<input name="seoTitle" value="${esc(p.seoTitle||'')}" maxlength="70" placeholder="Uses story title if blank"></label><label>Search description<textarea name="seoDescription" maxlength="180" placeholder="Uses introduction if blank">${esc(p.seoDescription||'')}</textarea></label><label>Publication date<input type="date" name="date" value="${p.date}" required></label><label>Status<select name="status"><option value="draft" ${p.status==='draft'?'selected':''}>Draft</option><option value="published" ${p.status==='published'?'selected':''}>Published</option></select></label><button class="btn" type="submit">Save story ${arrow}</button><p class="small">Published stories appear on the website after saving. Drafts stay private. The date is a display date, not a schedule.</p><p class="small" id="editor-state" role="status">All changes saved</p></aside></div></form>`);}
function setMeta(title,description){document.title=title+' | Stillwell';$('meta[name=description]').content=description||'A thoughtful space for mental wellbeing, care, and everyday perspectives.';$('meta[property="og:title"]').content=document.title;$('meta[property="og:description"]').content=$('meta[name=description]').content;$('link[rel=canonical]').href=location.origin+location.pathname;}
function render(){const path=decodeURI(location.pathname).replace(/\/$/,'')||'/';const carePage=careSite.renderCare(path,new URLSearchParams(location.search),providers);let html,title;if(path.startsWith('/admin')){title='Administrator workspace';html=!authenticated()?login():path==='/admin/providers'?adminShell(careAdmin.providerList(providers)):path==='/admin/providers/new'?adminShell(careAdmin.providerEditor()):path.startsWith('/admin/providers/')?adminShell(providers.some(p=>p.id===path.split('/').pop())?careAdmin.providerEditor(providers.find(p=>p.id===path.split('/').pop())):'<h1>Provider not found</h1><a href="/admin/providers">All providers</a>'):path==='/admin/enquiries'?adminShell(careAdmin.requestList(requests)):path==='/admin/new'?editor():path.startsWith('/admin/edit/')?editor(path.split('/').pop()):admin();}else if(carePage){html=layout(carePage.html);title=carePage.title;}else if(path==='/'){html=home();title='Therapy and psychiatry in India';}else if(path==='/blog'){html=blog();title='The journal';}else if(path.startsWith('/blog/')){const p=posts.find(p=>p.slug===path.split('/').pop()&&p.status==='published');html=article(path.split('/').pop());title=p?.seoTitle||p?.title||'Page not found';}else if(path==='/about'){html=about();title='Our approach';}else if(path==='/contact'){html=contact();title='Get in touch';}else if(path==='/privacy'){html=privacy();title='Privacy & preview terms';}else{html=notFound();title='Page not found';}$('#app').innerHTML=html;const current=posts.find(p=>'/blog/'+p.slug===path&&p.status==='published');setMeta(title,carePage?.description||current?.seoDescription||current?.excerpt);if(loadError)$('#app').insertAdjacentHTML('afterbegin',`<div class="notice" role="alert">${esc(loadError)} <button data-action="retry">Try again</button></div>`);editorDirty=false;}
// Browser behavior
function navigate(url){if(editorDirty&&!confirm('Leave this story without saving your changes?'))return;history.pushState({},'',url);render();if(location.hash){requestAnimationFrame(()=>$(location.hash)?.scrollIntoView({behavior:'instant',block:'start'}))}else window.scrollTo(0,0);}
window.addEventListener('popstate',()=>{render();window.scrollTo(0,0)});
window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue='';}});
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function showDialog(content){const d=$('#care-dialog');d.innerHTML=`<button class="icon-button dialog-close" data-action="close-dialog" aria-label="Close dialog">×</button>${content}`;if(!d.open)d.showModal();}
function careDialog(choice){if(choice!==undefined){const c=care[Number(choice)];showDialog(`<h2>${c.name}</h2><p>${c.text}</p><div class="notice">You’re exploring a website concept. No booking is made and no personal details are collected here.</div><a class="btn" href="/contact" style="margin-top:25px" data-close-dialog>Explore an enquiry ${arrow}</a><button class="text-link" style="border:0;background:none;margin-left:18px" data-action="care">Back to options</button>`);return;}showDialog(`<h2>Where would you like to start?</h2><p>Choose what feels closest to you. It’s okay to explore.</p>${care.map((c,i)=>`<button class="choice" data-action="care" data-choice="${i}"><span><strong>${c.name}</strong><small>${c.details.join(' · ')}</small></span>${arrow}</button>`).join('')}<a href="/contact" class="text-link" data-close-dialog>I’m not sure yet ${arrow}</a>`);}
document.addEventListener('click',async e=>{const a=e.target.closest('a[href]');if(a&&a.origin===location.origin&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();if(a.hasAttribute('data-close-dialog'))$('#care-dialog').close();navigate(a.pathname+a.search+a.hash);return;}const step=e.target.closest('[data-request-next],[data-request-back]');if(step){careSite.requestStep(step.closest('form'),step.hasAttribute('data-request-next')?1:-1);return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
if(action==='menu'){const open=$('.nav-links').classList.toggle('open');b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Close navigation':'Open navigation');b.textContent=open?'×':'☰';}
if(action==='care')navigate('/get-started');
if(action==='refresh-care'){b.disabled=true;try{requests=await cms.loadRequests();render();}catch(error){toast(error.message);}finally{b.disabled=false;}}
if(action==='close-dialog')$('#care-dialog').close();
if(action==='theme'){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('stillwell-theme',next)}catch{}}
if(action==='care-tab'){activeCare=Number(b.dataset.index);document.querySelectorAll('[data-action=care-tab]').forEach(t=>{t.setAttribute('aria-selected',t===b);t.tabIndex=t===b?0:-1;});$('#care-panel').innerHTML=carePanel();$('#care-panel').setAttribute('aria-labelledby',b.id);}
if(action==='blog-filter'){blogCategory=b.dataset.category;document.querySelectorAll('[data-action=blog-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',t===b)});$('#blog-results').innerHTML=blogResults();}
if(action==='reset-blog'){blogCategory='All articles';blogSearch='';render();}
if(action==='admin-filter'){adminFilter=b.dataset.filter;document.querySelectorAll('[data-action=admin-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',t===b)});$('#admin-results').innerHTML=adminResults();}
if(action==='retry')await initialize();
if(action==='logout'){if(editorDirty&&!confirm('Exit without saving your changes?'))return;b.disabled=true;try{await cms.signOut();posts=[];editorDirty=false;await initialize();navigate('/admin');}catch(error){toast(error.message)}finally{b.disabled=false;}}
if(action==='toggle-post'){b.disabled=true;try{const p=posts.find(p=>p.id===b.dataset.id);const saved=await cms.savePost({...p,status:p.status==='published'?'draft':'published'});posts=posts.map(p=>p.id===saved.id?saved:p);render();toast(saved.status==='published'?'Story published.':'Story unpublished.');}catch(error){toast(error.message)}finally{b.disabled=false;}}
if(action==='delete-post'){const p=posts.find(p=>p.id===b.dataset.id);showDialog(`<h2>Delete this story?</h2><p>“${esc(p.title)}” will be permanently removed from the journal.</p><button class="btn" data-action="confirm-delete" data-id="${esc(p.id)}">Delete story</button> <button class="btn light" data-action="close-dialog">Keep story</button>`);}
if(action==='confirm-delete'){b.disabled=true;try{const p=posts.find(p=>p.id===b.dataset.id);await cms.deletePost(p);posts=posts.filter(x=>x.id!==p.id);$('#care-dialog').close();render();toast('Story deleted.');await cms.removeUnusedImage(p.image);}catch(error){toast(error.message)}finally{b.disabled=false;}}
if(action==='format'){const t=$('#post-body'),start=t.selectionStart,end=t.selectionEnd;const selected=t.value.slice(start,end)||'Your text';const wrap=b.dataset.format==='bold'?`**${selected}**`:b.dataset.format==='italic'?`*${selected}*`:`\n\n## ${selected}\n\n`;t.setRangeText(wrap,start,end,'select');t.focus();editorDirty=true;$('#editor-state').textContent='Unsaved changes';}
if(action==='preview-post'){const f=$('#editor-form'),data=new FormData(f);showDialog(`<div class="preview-content"><p class="small">Story preview</p><h2>${esc(data.get('title')||'Untitled story')}</h2><p style="margin:20px 0">${esc(data.get('excerpt'))}</p><img src="${safeImage(data.get('image'))}" alt="${esc(data.get('imageAlt'))}" style="border-radius:15px;margin:20px 0"><div class="article-body">${markdown(data.get('body'))}</div></div>`);}
});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')],i=tabs.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click();}});
document.addEventListener('input',e=>{careSite.handleInput(e.target);if(e.target.closest('#provider-form')){editorDirty=true;$('#provider-state').textContent='Unsaved changes';}if(e.target.id==='blog-search'){blogSearch=e.target.value;$('#blog-results').innerHTML=blogResults();}if(e.target.id==='admin-search'){adminSearch=e.target.value;$('#admin-results').innerHTML=adminResults();}if(e.target.closest('#editor-form')){editorDirty=true;$('#editor-state').textContent='Unsaved changes';}});
document.addEventListener('change',async e=>{if(e.target.id==='request-status-filter')$('#request-results').innerHTML=careAdmin.requestRows(requests,e.target.value);if(e.target.name!=='imageFile')return;const file=e.target.files[0];if(!file)return;const f=e.target.closest('form');uploadPending=true;e.target.disabled=true;$('#editor-state').textContent='Uploading image…';let objectUrl;
try{objectUrl=URL.createObjectURL(file);const decoded=new Image();decoded.src=objectUrl;await decoded.decode();const url=await cms.uploadImage(file);if(!f.isConnected)return;$('#upload-preview').src=url;$('[name=image]',f).value=url;editorDirty=true;$('#editor-state').textContent='Image uploaded · Save your story to keep this change';}catch(error){toast(error.message||'This image could not be uploaded.');$('#editor-state').textContent='Image upload failed. Please try again.';}finally{if(objectUrl)URL.revokeObjectURL(objectUrl);uploadPending=false;e.target.disabled=false;}});
document.addEventListener('reset',e=>{if(e.target.id==='directory-form')requestAnimationFrame(()=>$('#directory-results').innerHTML=careSite.directoryResults(providers));});
document.addEventListener('submit',async e=>{
if(e.target.id==='directory-form'){e.preventDefault();$('#directory-results').innerHTML=careSite.directoryResults(providers,Object.fromEntries(new FormData(e.target)));return;}
if(e.target.id==='reflection-form'){e.preventDefault();careSite.reflect(e.target);return;}
if(e.target.id==='care-request-form'){e.preventDefault();const f=e.target;if(f.dataset.submitting)return;f.querySelectorAll('fieldset').forEach(el=>el.disabled=false);const d=new FormData(f);if(d.get('website'))return;if(d.get('service')==='Teen therapy'&&d.get('relationship')!=='Parent or legal guardian'){$('#request-error').textContent='A parent or legal guardian must start teen therapy enquiries.';careSite.requestStep(f,-2);return;}const payload={};for(const key of ['contact_name','email','phone','city','service','mode','language','relationship','professional_details'])payload[key]=String(d.get(key)||'').trim();payload.kind=f.dataset.kind;payload.provider_id=d.get('provider_id')||null;payload.consent=d.get('consent')==='on';const b=$('button[type=submit]',f);b.disabled=true;f.dataset.submitting='true';b.textContent='Saving test enquiry…';try{await cms.submitRequest(payload);f.innerHTML='<div class="notice" role="status"><h2>Your test enquiry is saved.</h2><p>The administrator can now review it in Care enquiries. No email has been sent and no appointment has been booked.</p><a class="text-link" href="/services">Explore care options ↗</a></div>';if(authenticated())requests=await cms.loadRequests();}catch(error){$('#request-error').textContent=error.message;f.querySelectorAll('[data-form-step]').forEach((el,i)=>el.disabled=i!==2);}finally{delete f.dataset.submitting;b.disabled=false;b.textContent='Submit test enquiry ↗';}return;}
if(e.target.id==='provider-form'){e.preventDefault();const f=e.target,d=new FormData(f),b=$('button[type=submit]',f),p={id:f.dataset.id||undefined};for(const k of ['name','slug','profession','credentials','registration','city','bio'])p[k]=String(d.get(k)||'').trim();p.languages=String(d.get('languages')).split(',').map(s=>s.trim()).filter(Boolean);p.specialties=String(d.get('specialties')).split(',').map(s=>s.trim()).filter(Boolean);p.modes=d.get('modes')==='Online and in person'?['Online','In person']:[d.get('modes')];p.verified=d.get('verified')==='on';p.active=d.get('active')==='on';if(p.active&&!p.verified){$('#provider-state').textContent='Verify credentials before publishing this profile.';return;}if(p.active&&['Psychiatrist','Clinical psychologist'].includes(p.profession)&&!p.registration){$('#provider-state').textContent='Add a professional registration before publishing.';return;}if(!p.languages.length||p.languages.length>12||p.specialties.length>20){$('#provider-state').textContent='Add 1–12 languages and up to 20 areas of focus.';return;}b.disabled=true;try{const saved=await cms.saveProvider(p);providers=[saved,...providers.filter(x=>x.id!==saved.id)].sort((a,b)=>a.name.localeCompare(b.name));editorDirty=false;navigate('/admin/providers');toast('Provider saved.');}catch(error){$('#provider-state').textContent=error.message;}finally{b.disabled=false;}return;}
if(e.target.matches('.request-status-form')){e.preventDefault();const f=e.target,b=$('button',f);b.disabled=true;try{const saved=await cms.updateRequest(f.dataset.id,new FormData(f).get('status'));requests=requests.map(r=>r.id===saved.id?saved:r);$('#request-results').innerHTML=careAdmin.requestRows(requests,$('#request-status-filter').value);toast('Enquiry status saved.');}catch(error){$('p[role=status]',f).textContent=error.message;}finally{b.disabled=false;}return;}

if(e.target.id==='login-form'){e.preventDefault();const f=e.target,b=$('button[type=submit]',f),d=new FormData(f);b.disabled=true;b.textContent='Signing in…';$('#login-error').textContent='';try{await cms.signIn(d.get('email').trim(),d.get('password'));[posts,providers,requests]=await Promise.all([cms.loadPosts(),cms.loadProviders(),cms.loadRequests()]);loadError='';render();}catch(error){$('#login-error').textContent=error.message;}finally{b.disabled=false;b.textContent='Sign in';}return;}
if(e.target.id==='contact-form'){e.preventDefault();showDialog('<h2>Your enquiry preview is ready.</h2><p>The form is complete. In the live website, this would be sent to the care team.</p><div class="notice">No message was sent or stored. Connect an email delivery service before launch.</div><button class="btn" style="margin-top:25px" data-action="close-dialog">Back to the website</button>');e.target.reset();return;}
if(e.target.id!=='editor-form')return;e.preventDefault();if(uploadPending){toast('Wait for the image upload to finish.');return;}if(savePending)return;
const f=e.target,d=new FormData(f),title=d.get('title').trim(),body=d.get('body').trim();if(!title||!body){toast('Add a title and story content before saving.');return;}
const slug=d.get('slug').trim()||title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!slug||slug.length>150){toast('Choose an article URL of up to 150 lowercase letters, numbers, and hyphens.');return;}
const tags=[...new Set(d.get('tags').split(',').map(t=>t.trim()).filter(Boolean))];if(tags.length>12){toast('Use up to 12 tags.');return;}
const previous=posts.find(p=>p.id===f.dataset.id);
const post={id:f.dataset.id,version:Number(f.dataset.version)||undefined,title,body,slug,excerpt:d.get('excerpt').trim(),image:d.get('image'),imageAlt:d.get('imageAlt').trim(),category:d.get('category'),date:d.get('date'),status:d.get('status'),tags,seoTitle:d.get('seoTitle').trim(),seoDescription:d.get('seoDescription').trim()};
const b=$('button[type=submit]',f);savePending=true;b.disabled=true;$('#editor-state').textContent='Saving…';
try{const saved=await cms.savePost(post);posts=[saved,...posts.filter(p=>p.id!==saved.id)];editorDirty=false;navigate('/admin');toast(saved.status==='published'?'Story published on your website.':'Draft saved.');if(previous?.image!==saved.image&&previous)await cms.removeUnusedImage(previous.image);}catch(error){$('#editor-state').textContent=error.message;toast(error.message);}finally{savePending=false;b.disabled=false;}
});
$('#care-dialog').addEventListener('click',e=>{if(e.target===$('#care-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
async function initialize(){try{await cms.verifyAdministrator();[posts,providers,requests]=await Promise.all([cms.loadPosts(),cms.loadProviders(),cms.loadRequests()]);loadError='';}catch(error){loadError=error.message;}render();}
cms.client.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){cms.clearAdministrator();requests=[];providers=providers.filter(p=>p.active&&p.verified);posts=posts.filter(p=>p.status==='published');editorDirty=false;render();}});
render();initialize();
